$$('[data-field]').forEach(i=>i.onchange=()=>{const v=Number(i.value);if(!Number.isFinite(v)||!i.checkValidity()){toast('Enter a number within the displayed limits.');i.value=state[i.dataset.group][i.dataset.field];return;}state[i.dataset.group][i.dataset.field]=v;save();render();});
$('#language').onchange=e=>{state.language=e.target.value;save();render();};
