function action(a){({editor,search:searchLocation,generate,assumptions,compare,bill,evidence,export:report,help,shared,explain:()=>modal('Understanding your solar estimate',`<div class="dialog-body"><p>${explanation(selectedCapacity())}</p>${formulaDetails()}</div>`),costs,weights,survey,scenario,monitor,'upload-media':openRoofMedia,'zoom-in':()=>zoom(1.2),'zoom-out':()=>zoom(.8),'reset-view':()=>{$('#town').style.transform='';}}[a]||(()=>{}))();}
function zoom(f){const el=$('#town');if(el){el.dataset.scale=Math.min(2,Math.max(.7,(Number(el.dataset.scale)||1)*f));el.style.transform=`scale(${el.dataset.scale})`;}}
function generate(){const max=layout(state.roof,state.exclusions,state.a,Math.floor(state.a.load*1000/state.a.watt));if(!max.length){toast('No panels fit with these dimensions, exclusions and setbacks.');return;}const opts=max.map((_,i)=>solar(i+1,state.a)).filter(s=>s.annual>0);opts.sort((a,b)=>(a.payback??Infinity)-(b.payback??Infinity));const best=opts[0];state.panels=max.slice(0,best?.count||1);save();render();toast(`Placed ${state.panels.length} panels: lowest simple payback among valid grid layouts. Review in the editor.`);}
function formModal(title,body,onSave){modal(title,`<form id="modal-form" class="dialog-body">${body}<div class="dialog-actions"><button type="button" class="outline" id="cancel">Cancel</button><button class="primary" type="submit">Save changes</button></div></form>`);$('#cancel').onclick=()=>$('#dialog').close();$('#modal-form').onsubmit=e=>{e.preventDefault();onSave(new FormData(e.target));};}
function input(name,label,value,min=0,max=100000,step=1){return `<label class="field">${label}<input name="${name}" type="number" value="${value}" min="${min}" max="${max}" step="${step}" required></label>`;}
function assumptions(){const a=state.a;formModal('Solar assumptions',`<p class="muted">Editable planning inputs, not a quotation or generation forecast.</p><div class="form-grid">${input('yield','Monthly yield · kWh/kW',a.yield,1,500)}${input('selfUse','Self-consumption share · %',a.selfUse,0,100)}${input('exportRate','Export credit · ₹/kWh',a.exportRate,0,100,.1)}${input('load','Sanctioned load · kW',a.load,.1,1000,.1)}${input('quote','Installed cost · ₹/kW',a.quote,1,1000000)}${input('opex','Annual maintenance · % of cost',a.opex,0,100,.1)}${input('watt','Panel rated power · W',a.watt,50,1000,10)}${input('length','Panel length · m',a.length,.2,5,.1)}${input('width','Panel width · m',a.width,.2,5,.1)}${input('setback','Boundary setback · m',a.setback,0,5,.1)}${input('spacing','Panel spacing · m',a.spacing,0,5,.1)}</div><label class="checkbox"><input type="checkbox" name="subsidy" ${a.subsidy?'checked':''}> Include standard residential subsidy assumption</label><p class="tiny">Saving regenerates the layout to respect changed dimensions, load and spacing. Current subsidy eligibility must be verified through the official programme.</p>`,fd=>{for(const k of Object.keys(a))if(k!=='subsidy'&&fd.has(k))a[k]=Number(fd.get(k));a.subsidy=fd.has('subsidy');state.panels=layout(state.roof,state.exclusions,a,Math.min(state.panels.length,Math.floor(a.load*1000/a.watt)));save();$('#dialog').close();render();});}
function bill(){formModal('Review electricity bill values',`<p class="muted">Enter values from your bill. Nothing is uploaded or sent to an AI service in this demo.</p><div class="form-grid">${input('units','Consumption for billing period · kWh',state.a.consumption)}${input('days','Billing period · days',30,1,366)}${input('tariff','Energy tariff · ₹/kWh',state.a.tariff,0,100,.1)}${input('load','Sanctioned load · kW',state.a.load,.1,1000,.1)}</div><div class="note"><p>Monthly use = billed units × 30 ÷ billing days. Exclude fixed charges when entering the energy tariff.</p></div>`,fd=>{state.a.consumption=Math.round(Number(fd.get('units'))*30/Number(fd.get('days')));state.a.tariff=Number(fd.get('tariff'));state.a.load=Number(fd.get('load'));state.panels=state.panels.slice(0,Math.floor(state.a.load*1000/state.a.watt));save();$('#dialog').close();render();toast('Bill values confirmed and applied.');});}
function compare(){const max=layout(state.roof,state.exclusions,state.a,Math.floor(state.a.load*1000/state.a.watt)).length;const options=Array.from({length:max},(_,i)=>solar(i+1,state.a));let best=[...options].filter(s=>s.annual>0).sort((a,b)=>a.payback-b.payback)[0];modal('Compare feasible system sizes',`<div class="dialog-body"><p class="muted">Recommended = lowest positive simple payback among grid layouts within your sanctioned load. Actual roof geometry and electrical constraints can reduce feasible capacity.</p><div class="table-scroll"><table><thead><tr><th>System</th><th>Generation / mo</th><th>Net cost</th><th>Net savings / yr</th><th>Payback</th><th></th></tr></thead><tbody>${options.map(s=>`<tr class="${best?.count===s.count?'recommended':''}"><td><strong>${s.capacity.toFixed(1)} kW</strong>${best?.count===s.count?'<small>Recommended</small>':''}</td><td>${Math.round(s.generation)} kWh</td><td>${money(s.net)}</td><td>${money(s.annual)}</td><td>${s.payback===null?'No positive payback':s.payback.toFixed(1)+' yr'}</td><td><button class="text-btn" data-pick="${s.count}">Use plan</button></td></tr>`).join('')||'<tr><td colspan="6">No panels fit. Edit your roof or assumptions.</td></tr>'}</tbody></table></div>${formulaDetails()}</div>`);$$('[data-pick]').forEach(b=>b.onclick=()=>{state.panels=layout(state.roof,state.exclusions,state.a,Number(b.dataset.pick));save();$('#dialog').close();render();});}
function formulaDetails(){return `<details class="details"><summary>Calculation methods & limitations</summary><p>Capacity = panel count × rated watts / 1,000. Generation = capacity × monthly yield. Self-consumption is capped at household demand. Exports = generation − self-consumed energy.</p><p>Annual net savings = 12 × (self-consumed units × retail tariff + exported units × export credit) − annual maintenance. Simple payback = net installed cost / annual net savings; absent when savings are not positive.</p><p>Subsidy assumption: ₹30,000 per kW up to 2 kW, then ₹18,000 for the next 1 kW; capped at ₹78,000 and installation cost. Only solar is eligible in this model. No financing, degradation, tariff escalation or fixed-charge savings included.</p></details>`;}
function editor(){state.draft=[];state.tool='select';modal('Your roof, in detail',`<div class="dialog-body editor-body"><div class="editor-toolbar"><button class="outline active" data-tool="select">${icon('edit')} Move / edit</button><button class="outline" data-tool="draw">Draw boundary</button><button class="outline" data-tool="exclude">Add exclusion</button><button class="outline" id="add-panel">+ Panel</button><button class="outline" id="rotate-panel">Rotate</button><button class="outline danger" id="delete-item">Remove</button></div><p id="editor-hint" class="tiny">Drag blue panels or green boundary points. Click an exclusion to select it. Panel movement is checked against setbacks, spacing and exclusions.</p><div id="roof-editor"></div><div class="editor-info" id="editor-info"></div><div class="dialog-actions"><button class="text-btn" id="reset-roof">Reset demo roof</button><button class="outline" id="finish-draw">Finish boundary</button><button class="primary" id="confirm-roof">Confirm roof & layout ${icon('check')}</button></div></div>`);$('#dialog').classList.add('wide');drawEditor();$$('[data-tool]').forEach(b=>b.onclick=()=>{state.tool=b.dataset.tool;state.draft=[];$$('[data-tool]').forEach(x=>x.classList.toggle('active',x===b));$('#editor-hint').textContent=state.tool==='draw'?'Click at least 3 points, then Finish boundary. Coordinates are metres in a local roof plane.':state.tool==='exclude'?'Click to add a 1.5 × 1.5 m exclusion. Panels intersecting it will be removed.':'Drag panels or boundary points. Click a panel or exclusion to select it.';drawEditor();});$('#add-panel').onclick=()=>{const free=layout(state.roof,state.exclusions,state.a).find(r=>validPanel(r,state.roof,state.exclusions,state.panels,state.a));if(!free||((state.panels.length+1)*state.a.watt/1000>state.a.load)){toast('No valid free slot within roof and sanctioned-load limits.');return;}free.id=Date.now();state.panels.push(free);state.selected={type:'panel',id:free.id};save();drawEditor();};$('#rotate-panel').onclick=()=>{let p=state.panels.find(p=>p.id===state.selected?.id&&state.selected.type==='panel');if(!p){toast('Select a panel first.');return;}let r={...p,w:p.h,h:p.w};if(validPanel(r,state.roof,state.exclusions,state.panels.filter(x=>x!==p),state.a)){Object.assign(p,r);save();drawEditor();}else toast('Rotation would overlap a panel, exclusion or setback.');};$('#delete-item').onclick=()=>{if(!state.selected)return toast('Select a panel or exclusion.');if(state.selected.type==='panel')state.panels=state.panels.filter(p=>p.id!==state.selected.id);else if(state.selected.type==='exclusion')state.exclusions.splice(state.selected.id,1);state.selected=null;save();drawEditor();};$('#finish-draw').onclick=()=>{if(state.tool!=='draw'||!simple(state.draft))return toast('Draw a non-crossing boundary with at least 3 points and 1 m².');state.roof=structuredClone(state.draft);state.draft=[];state.tool='select';state.confirmed=false;revalidate();save();drawEditor();};$('#reset-roof').onclick=()=>{state.roof=structuredClone(roofDefault);state.exclusions=[{x:8.3,y:1,w:2.1,h:2.3}];state.panels=layout(state.roof,state.exclusions,state.a,Math.min(6,Math.floor(state.a.load*1000/state.a.watt)));state.confirmed=false;save();drawEditor();};$('#confirm-roof').onclick=()=>{if(state.draft.length)return toast('Finish or cancel drawing before confirming.');state.confirmed=true;save();$('#dialog').close();$('#dialog').classList.remove('wide');render();};}
function revalidate(){const valid=[];for(const p of state.panels)if(validPanel(p,state.roof,state.exclusions,valid,state.a))valid.push(p);state.panels=valid;}
function drawEditor(){const scale=34,ox=75,oy=45,xy=p=>`${ox+p.x*scale},${oy+p.y*scale}`;$('#roof-editor').innerHTML=`<svg id="editor-svg" viewBox="0 0 680 480" aria-label="Roof geometry editor in metres"><defs><pattern id="grid" x="${ox}" y="${oy}" width="34" height="34" patternUnits="userSpaceOnUse"><path d="M34 0H0v34" fill="none" stroke="#d9e3dd" stroke-width=".7"/></pattern></defs><rect width="680" height="480" fill="#f4f7f3"/><rect width="680" height="480" fill="url(#grid)"/><polygon points="${state.roof.map(xy).join(' ')}" fill="#e8eddf" stroke="#168774" stroke-width="2"/><polygon points="${state.roof.map(xy).join(' ')}" fill="none" stroke="#168774" stroke-opacity=".12" stroke-width="${state.a.setback*scale*2}"/>${state.exclusions.map((r,i)=>`<g data-exclusion="${i}"><rect x="${ox+r.x*scale}" y="${oy+r.y*scale}" width="${r.w*scale}" height="${r.h*scale}" fill="#f1b8a7" stroke="${state.selected?.type==='exclusion'&&state.selected.id===i?'#a5321b':'#d57e64'}" stroke-width="2"/><text x="${ox+(r.x+r.w/2)*scale}" y="${oy+(r.y+r.h/2)*scale}" text-anchor="middle" font-size="9" fill="#9d4a32">Exclusion</text></g>`).join('')}${state.panels.map(p=>`<g data-panel="${p.id}" class="draggable"><rect x="${ox+p.x*scale}" y="${oy+p.y*scale}" width="${p.w*scale}" height="${p.h*scale}" rx="2" fill="#25678a" stroke="${state.selected?.type==='panel'&&state.selected.id===p.id?'#f8c94b':'#a9d8e8'}" stroke-width="3"/><path d="M${ox+(p.x+p.w/2)*scale} ${oy+p.y*scale}v${p.h*scale}" stroke="#80aec5"/><text x="${ox+(p.x+p.w/2)*scale}" y="${oy+(p.y+p.h/2)*scale+3}" text-anchor="middle" font-size="9" fill="white">${state.panels.indexOf(p)+1}</text></g>`).join('')}${state.roof.map((p,i)=>`<circle data-vertex="${i}" cx="${ox+p.x*scale}" cy="${oy+p.y*scale}" r="6" fill="white" stroke="#118b73" stroke-width="3" class="draggable"/>`).join('')}${state.draft.length?`<polyline points="${state.draft.map(xy).join(' ')}" fill="#d3eee0" stroke="#0a7f63" stroke-width="2"/>${state.draft.map(p=>`<circle cx="${ox+p.x*scale}" cy="${oy+p.y*scale}" r="4" fill="#0a7f63"/>`).join('')}`:''}<text x="20" y="460" font-size="12" fill="#6a7c70">1 grid square = 1 m · local metric coordinates · flat roof only</text></svg>`;
$('#editor-info').innerHTML=`<span><b>${area(state.roof).toFixed(1)} m²</b> roof</span><span><b>≈ ${usableArea(state.roof,state.exclusions,state.a.setback).toFixed(1)} m²</b> usable</span><span><b>${state.panels.reduce((s,p)=>s+p.w*p.h,0).toFixed(1)} m²</b> panel footprint</span><span><b>${state.panels.reduce((s,p)=>s+(p.w+state.a.spacing)*(p.h+state.a.spacing),0).toFixed(1)} m²</b> spaced module area*</span><span><b>${selectedCapacity().capacity.toFixed(1)} kW</b></span><small>*Includes assigned spacing; site access corridors require installer design. Usable area uses a 0.1 m sampling grid.</small>`;
const svg=$('#editor-svg');const point=e=>{const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const c=p.matrixTransform(svg.getScreenCTM().inverse());return {x:Math.round((c.x-ox)/scale*10)/10,y:Math.round((c.y-oy)/scale*10)/10};};svg.onpointerdown=e=>{const pt=point(e);if(state.tool==='draw'){state.draft.push(pt);drawEditor();return;}if(state.tool==='exclude'){const r={x:pt.x,y:pt.y,w:1.5,h:1.5};state.exclusions.push(r);state.confirmed=false;revalidate();save();drawEditor();return;}const panel=e.target.closest('[data-panel]'),v=e.target.closest('[data-vertex]'),ex=e.target.closest('[data-exclusion]');if(panel){state.selected={type:'panel',id:Number(panel.dataset.panel)};const p=state.panels.find(x=>x.id===state.selected.id);dragging={type:'panel',id:p.id,start:pt,orig:{...p}};}else if(v){dragging={type:'vertex',id:Number(v.dataset.vertex),orig:structuredClone(state.roof)};}else if(ex){state.selected={type:'exclusion',id:Number(ex.dataset.exclusion)};drawEditor();}svg.setPointerCapture?.(e.pointerId);};svg.onpointerup=e=>{if(!dragging)return;const pt=point(e);if(dragging.type==='panel'){const p=state.panels.find(p=>p.id===dragging.id),r={...p,x:Math.round((dragging.orig.x+pt.x-dragging.start.x)*10)/10,y:Math.round((dragging.orig.y+pt.y-dragging.start.y)*10)/10};if(validPanel(r,state.roof,state.exclusions,state.panels.filter(x=>x!==p),state.a))Object.assign(p,r);else toast('Move rejected: panel overlaps a boundary, exclusion or another panel.');}else{const poly=structuredClone(state.roof);poly[dragging.id]=pt;if(simple(poly)){state.roof=poly;state.confirmed=false;revalidate();}else toast('Boundary must not cross itself.');}dragging=null;save();drawEditor();};svg.onpointercancel=()=>dragging=null;}
function costs(){formModal('Programme cost assumptions',`<p class="muted">Illustrative arithmetic; obtain dated local quotations. The installed rate includes labour. Maintenance and recoating are additional and not estimated.</p><div class="form-grid">${input('rate','Installed coating rate · ₹/m²',state.cool.rate,0)}${input('prep','Preparation / repairs per home · ₹',state.cool.prep,0)}${input('overhead','Total programme overhead · ₹',state.cool.overhead,0,100000000)}</div><p class="tiny">Household cost = treatment area × installed rate + preparation. Total = funded homes × household cost + overhead. Costs for other interventions require a quote.</p>`,fd=>{for(const k of ['rate','prep','overhead'])state.cool[k]=Number(fd.get(k));if(state.cool.overhead>state.cool.budget){toast('Overhead exceeds the programme budget. Increase the budget or reduce overhead.');return;}save();$('#dialog').close();render();});}
function weights(){formModal('Explainable priority ranking',`<p class="muted">Scores are normalised by the sum of weights. Need is ranked before cost. Unknown vulnerability uses a neutral 50/100 placeholder and makes the result provisional.</p><div class="form-grid">${Object.entries(state.weights).map(([k,v])=>input(k,{heat:'Heat exposure',housing:'Housing condition',green:'Lack of green cover',vulnerability:'Household vulnerability'}[k]+' · weight',v,0,100)).join('')}</div>`,fd=>{const next=Object.fromEntries(Object.keys(state.weights).map(k=>[k,Number(fd.get(k))]));if(!Object.values(next).some(v=>v>0))return toast('At least one ranking weight must be positive.');state.weights=next;save();$('#dialog').close();render();});}
function survey(){const r=rows.find(r=>r.name===state.neighbour);formModal('Survey — '+r.name,`<p class="muted">Enter verified aggregate observations. Do not infer household vulnerability or ventilation quality from imagery.</p><div class="form-grid">${input('households','Surveyed eligible households',r.households,0,100000)}${input('housing','Housing need score · 0–100',r.housing,0,100)}${input('vulnerability','Vulnerability score · 0–100',r.vulnerability??50,0,100)}</div><label class="checkbox"><input name="confirmed" type="checkbox" required> I confirm these values come from a survey.</label>`,fd=>{r.households=Number(fd.get('households'));r.housing=Number(fd.get('housing'));r.vulnerability=Number(fd.get('vulnerability'));r.survey=true;state.cool.households=r.households;state.surveys=structuredClone(rows);save();$('#dialog').close();render();});}
function scenario(){modal('Cooling scenario — relative potential',`<div class="dialog-body"><p class="muted">Explore intervention coverage. The colours indicate relative coverage, not predicted degrees of cooling. Mature tree canopy is a future scenario.</p><label class="field">Roof coating coverage <output id="cover-value">${state.cool.coverage}%</output><input id="coverage" type="range" min="0" max="100" value="${state.cool.coverage}"></label><label class="field">Future mature canopy <output id="canopy-value">${state.cool.canopy}%</output><input id="canopy" type="range" min="0" max="80" value="${state.cool.canopy}"></label><div class="scenario-preview"><div><small>Observed heat context</small><div class="heat-block"><span>44.2°C</span><small>Synthetic surface temperature</small></div></div><div><small>Intervention coverage scenario</small><div class="potential-block" id="potential"><span id="potential-label"></span><small>Relative potential · not °C</small></div></div></div><p class="note">No additive temperature benefit is assumed. Check future tree shading of solar panels, land rights, utilities and maintenance. New saplings do not provide mature-canopy shade.</p><button class="primary" id="save-scenario">Save scenario</button></div>`);const update=()=>{$('#cover-value').value=$('#coverage').value+'%';$('#canopy-value').value=$('#canopy').value+'%';$('#potential-label').textContent=$('#coverage').value+'% roofs / '+$('#canopy').value+'% canopy';$('#potential').style.background=`linear-gradient(125deg,#bfdac0 ${$('#coverage').value}%,#f0d5a8)`;};$('#coverage').oninput=update;$('#canopy').oninput=update;update();$('#save-scenario').onclick=()=>{state.cool.coverage=Number($('#coverage').value);state.cool.canopy=Number($('#canopy').value);save();$('#dialog').close();toast('Scenario saved with assumptions.');};}
function shared(){const footprint=state.panels.reduce((s,p)=>s+p.w*p.h,0),usable=usableArea(state.roof,state.exclusions,state.a.setback);modal('Shared roof use & shading checks',`<div class="dialog-body"><div class="form-grid"><div class="large-stat"><small>Solar panel footprint</small><strong>${footprint.toFixed(1)} m²</strong></div><div class="large-stat"><small>Usable area minus panels ≈</small><strong>${Math.max(0,usable-footprint).toFixed(1)} m²</strong></div></div><p>This remaining area is not automatically available for coating: panel spacing, access, waterproofing and coating compatibility need review.</p><ul><li>Verify mounting access and drainage before coating around arrays.</li><li>Check future tree growth for shading conflicts.</li><li>Do not add solar shading and coating temperature benefits.</li><li>No year-round shade or structural assessment is available from this concept.</li></ul><label class="checkbox"><input id="before" type="checkbox" ${state.before?'checked':''}> Show original roof without proposed panels</label></div>`);$('#before').onchange=e=>{state.before=e.target.checked;save();render();};}
function monitor(){modal('Site verification & pilot monitoring',`<form id="pilot-form" class="dialog-body"><p class="muted">Use paired indoor measurements over the same weather period. One reading cannot establish causal cooling performance.</p><div class="checklist">${['Roof structure and waterproofing','Electrical connection and sanctioned load','Seasonal shading and safe maintenance access','Material compatibility and local quotation'].map((t,i)=>`<label class="checkbox"><input type="checkbox" data-check="${i}" ${state.checks?.[i]?'checked':''}>${t}</label>`).join('')}</div><div class="form-grid"><label class="field">Observation date<input name="date" type="date" required></label>${input('treated','Treated indoor temperature · °C',30,-20,70,.1)}${input('control','Comparison indoor temperature · °C',31,-20,70,.1)}</div><label class="field">Context / same-weather notes<input name="notes" maxlength="300" placeholder="Roof material, monitoring time, sensor location"></label><button class="primary">Save observation</button><div class="observation-list">${state.monitor.map(m=>`<p><strong>${esc(m.date)}</strong> · treated ${m.treated}°C / comparison ${m.control}°C<br><small>${esc(m.notes)}</small></p>`).join('')||'<p class="tiny">No local observations recorded yet.</p>'}</div></form>`);$$('[data-check]').forEach(i=>i.onchange=()=>{state.checks??={};state.checks[i.dataset.check]=i.checked;save();});$('#pilot-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.monitor.push({date:f.get('date'),treated:Number(f.get('treated')),control:Number(f.get('control')),notes:f.get('notes')});save();monitor();toast('Observation saved. Estimates remain uncalibrated pending pilot review.');};}
function evidence(){modal('Evidence, data & assumptions',`<div class="dialog-body evidence-list"><div class="note amber-note"><p>This workspace uses a fictional neighbourhood, synthetic heat values and local metric roof geometry. Satellite imagery is context only. No income, ventilation or temperature is inferred from imagery.</p></div><article><span class="eyebrow">SOLAR · POLICY ASSUMPTION</span><h3>Residential subsidy</h3><p>The default formula follows the 1 March 2024 government overview. Check current eligibility, DISCOM requirements and quotations before committing.</p><a href="https://www.pib.gov.in/PressReleasePage.aspx?PRID=2010674" target="_blank" rel="noopener">Government scheme overview ↗</a> · <a href="https://www.pmsuryaghar.gov.in/" target="_blank" rel="noopener">Official programme ↗</a></article><article><span class="eyebrow">COOLING · LIMITED OBSERVATIONAL EVIDENCE</span><h3>Painted tin-roof reference scenario</h3><p>Vellingiri et al. (2020) studied 16 Ahmedabad households. A reflective-painted tin-roof household had approximately 1°C lower mean daytime indoor temperature than a comparison. This small cross-sectional study is not a universal prediction. Its ventilation intervention did not consistently cool homes.</p><a href="https://www.mahilahousingtrust.org/wp-content/uploads/2022/06/MHT_Combating-Climate-Change%E2%80%90induced-Heat-Stress.pdf" target="_blank" rel="noopener">Read the original study ↗</a></article><article><span class="eyebrow">HEAT · DISTINCT MEASUREMENTS</span><h3>Surface temperature ≠ indoor air temperature</h3><p>Thermal observations have different resolution and measurement meaning from building imagery. Real datasets must include date, resolution, cloud filtering and provenance. The demo has no measured satellite heat layer or acquisition date.</p><a href="https://www.epa.gov/heatislands/measuring-heat-islands" target="_blank" rel="noopener">EPA measurement guidance ↗</a></article><article><h3>Geometry and model status</h3><p>Manual outlines use metres in a local flat-roof plane. Roof area uses the shoelace formula; usable area is approximated on a 0.1 m grid, removing overlapping exclusions once. Panel fit checks full rectangles, setbacks, spacing and collisions. SAM and Gemini are not active in this hosted demo; optional backend adapters are included in the source project.</p></article>${formulaDetails()}</div>`);}
function help(){modal('Welcome to HeatHack Solar',`<div class="dialog-body"><p>Follow the two connected journeys from your brief.</p><ol class="guide"><li><strong>Find your location.</strong> Use satellite context or work with the illustrative neighbourhood.</li><li><strong>Confirm your roof.</strong> Open the editor, adjust the boundary, add exclusions and confirm.</li><li><strong>Shape your solar plan.</strong> Enter bill values, generate a layout and compare feasible sizes.</li><li><strong>Plan community cooling.</strong> Switch to My Neighbourhood, review survey needs and set your budget.</li><li><strong>Export and verify.</strong> Save a combined report and record site checks and pilot observations.</li></ol><div class="note"><p>Plans save in this browser. Export to keep a portable copy. AI extraction and segmentation need the optional configured backend; this demo uses manual inputs.</p></div></div>`);}
function report(){const s=selectedCapacity(),b=budget(state.cool);modal('Your combined plan',`<div class="dialog-body"><div class="report-title"><div class="brand-mark">${icon('sun')}</div><div><h3>HeatHack Solar</h3><p>${esc(state.location)} · preliminary plan</p></div></div><div class="form-grid"><div class="large-stat"><small>Solar capacity</small><strong>${s.capacity.toFixed(1)} kW</strong></div><div class="large-stat"><small>Annual net savings</small><strong>${money(s.annual)}</strong></div><div class="large-stat"><small>Coating cost per household</small><strong>${money(b.household)}</strong></div><div class="large-stat"><small>Coating programme reach</small><strong>${b.reached} homes</strong></div></div><p>${state.confirmed?'Roof outline confirmed by user.':'Roof outline not yet confirmed.'} Demo data and estimates require local verification.</p><div class="dialog-actions"><button id="download-json" class="outline">${icon('download')} Project JSON</button><button id="download-report" class="primary">${icon('file')} Download report</button></div><p class="tiny">The HTML report includes calculations, cooling assumptions, evidence links, roof geometry and pilot observations. Open it in a browser and Print → Save as PDF.</p><label class="field">Restore exported project<input type="file" id="import-plan" accept="application/json,.json"></label></div>`);$('#download-json').onclick=()=>download('heathack-plan.json',JSON.stringify({version:1,state,rows,solar:s,cooling:b,exportedAt:new Date().toISOString()},null,2),'application/json');$('#download-report').onclick=()=>download('heathack-plan.html',reportHTML(),'text/html');$('#import-plan').onchange=async e=>{try{const f=e.target.files[0];if(f.size>1000000)throw Error('File too large');const p=JSON.parse(await f.text());validateImport(p);Object.assign(state,p.state);state.tool='select';state.draft=[];state.view='concept';if(p.rows)rows.splice(0,rows.length,...p.rows);revalidate();save();$('#dialog').close();render();toast('Plan restored.');}catch(err){toast('Could not restore plan: '+err.message);}};}
function validateImport(p){if(p.version!==1||!p.state||!Array.isArray(p.state.roof)||!simple(p.state.roof)||p.state.roof.length>100)throw Error('Invalid HeatHack project');for(const [k,v] of Object.entries(defaults)){if(k==='subsidy'){if(typeof p.state.a[k]!=='boolean')throw Error('Invalid subsidy flag');}else if(!Number.isFinite(p.state.a[k])||p.state.a[k]<0)throw Error('Invalid solar assumptions');}if(p.state.a.length<.2||p.state.a.width<.2||p.state.a.watt<50)throw Error('Invalid panel dimensions');if(!Array.isArray(p.state.panels)||p.state.panels.length>1000||!Array.isArray(p.state.exclusions)||p.state.exclusions.length>100)throw Error('Invalid geometry');for(const r of [...p.state.panels,...p.state.exclusions])if(!['x','y','w','h'].every(k=>Number.isFinite(r[k]))||r.w<=0||r.h<=0)throw Error('Invalid rectangle');if(p.state.roof.some(r=>!Number.isFinite(r.x)||!Number.isFinite(r.y)||Math.abs(r.x)>100||Math.abs(r.y)>100))throw Error('Roof coordinates outside supported range');for(const k of ['area','rate','prep','households','budget','overhead','coverage','canopy'])if(!Number.isFinite(p.state.cool?.[k])||p.state.cool[k]<0)throw Error('Invalid cooling inputs');if(!['roof','neighbour'].includes(p.state.mode)||!Array.isArray(p.state.monitor))throw Error('Invalid plan state');}
function download(name,data,type){const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function reportHTML(){const s=selectedCapacity(),b=budget(state.cool);return `<!doctype html><html><meta charset="utf-8"><title>HeatHack Solar plan</title><style>body{font:15px/1.65 system-ui;max-width:900px;margin:50px auto;padding:20px;color:#233d34}h1,h2{color:#08775f}table{border-collapse:collapse;width:100%}td,th{padding:10px;text-align:left;border-bottom:1px solid #ddd}small{color:#66776b}svg{max-width:100%;height:400px}a{color:#08775f}@media print{body{margin:0}h2{break-after:avoid}table,svg{break-inside:avoid}}</style><h1>HeatHack Solar — Combined plan</h1><p>${esc(state.location)} · Exported ${new Date().toISOString().slice(0,10)}</p><p><strong>Preliminary concept · synthetic neighbourhood data · installer verification required.</strong></p><p>Roof confirmed: ${state.confirmed?'Yes':'No'}. AI services were not used for this plan.</p><h2>Solar layout</h2>${townMap()}<table>${Object.entries({Panels:s.count,'Capacity (kW)':s.capacity,'Monthly generation (kWh)':s.generation,'Self-consumed (kWh/month)':s.selfConsumed,'Exported (kWh/month)':s.exported,'Gross cost':money(s.gross),'Subsidy assumption':money(s.grant),'Net cost':money(s.net),'Annual net savings':money(s.annual),'Simple payback':s.payback===null?'No positive payback':s.payback.toFixed(1)+' years','Roof area':area(state.roof).toFixed(1)+' m²','Usable area (approximate)':usableArea(state.roof,state.exclusions,state.a.setback).toFixed(1)+' m²'}).map(([k,v])=>`<tr><th>${k}</th><td>${v}</td></tr>`).join('')}</table><h2>Solar assumptions</h2><pre>${esc(JSON.stringify(state.a,null,2))}</pre>${formulaDetails().replace('<details class="details">','<details open>')}<h2>Neighbourhood cooling</h2><p>Selected intervention: ${esc(state.cool.intervention)}. Selected roof material: ${esc(state.cool.material)}.</p><p>${state.cool.intervention==='coating'?`Coating arithmetic: ${state.cool.area} m² × ${money(state.cool.rate)}/m² + ${money(state.cool.prep)} preparation = ${money(b.household)}/household. ${b.reached} homes within ${money(state.cool.budget)} budget. Total ${money(b.total)}, including ${money(state.cool.overhead)} overhead.`:'Selected intervention requires a site assessment and local quotation. No programme cost or temperature reduction is estimated.'}</p><p>Indoor cooling: ${state.cool.intervention==='coating'&&state.cool.material==='tin'?'Reference scenario ≈ 1°C lower mean daytime indoor temperature for comparable painted tin roofs, from a small 16-household Ahmedabad study (2020). Local outcomes unverified.':'Assessment required; no matched numerical evidence.'} Not subtracted from surface temperature. Maintenance/recoating additional.</p><p>Scenario: ${state.cool.coverage}% roof coating coverage, ${state.cool.canopy}% future mature canopy. Relative coverage only, no combined temperature forecast.</p><h2>Priority ranking</h2><p>Weights: ${esc(JSON.stringify(state.weights))}. Missing vulnerability uses neutral 50 and triggers provisional confidence.</p><table><tr><th>Area</th><th>Need score</th><th>Confidence</th></tr>${rank(rows,state.weights).map(r=>`<tr><td>${esc(r.name)}</td><td>${r.score.toFixed(1)}</td><td>${r.provisional?'Survey required':'Demo survey; local verification required'}</td></tr>`).join('')}</table><h2>Evidence and limitations</h2><p><a href="https://www.pib.gov.in/PressReleasePage.aspx?PRID=2010674">PIB subsidy overview, 1 March 2024</a> · <a href="https://www.epa.gov/heatislands/measuring-heat-islands">EPA heat measurement guidance</a> · <a href="https://www.mahilahousingtrust.org/wp-content/uploads/2022/06/MHT_Combating-Climate-Change%E2%80%90induced-Heat-Stress.pdf">Vellingiri et al., 2020</a></p><p>Geometry uses a local metric flat-roof plane. Usable area uses a 0.1 m grid. Panel footprint differs from spacing and access area. No annual shade simulation, structural assessment or electrical certification. Cooling data are synthetic, with no satellite observation date. Costs are illustrative assumptions, not local quotations. Subsidy is not applied to cooling.</p><h2>Site verification and monitoring</h2><pre>${esc(JSON.stringify({checks:state.checks||{},observations:state.monitor},null,2))}</pre><p>Verify structure, shading, wiring, coatings and local eligibility. Refine estimates only after a matched, same-weather pilot.</p></html>`;}
async function initSatellite(){if(!window.L){$('#map-canvas').innerHTML='<div class="map-unavailable"><h3>Satellite view unavailable</h3><p>The map library needs an internet connection. Your concept planner still works offline.</p></div>';return;}$('#map-canvas').innerHTML='<div id="live-map"></div>';liveMap=L.map('live-map',{zoomControl:false}).setView(state.coords||[23.0225,72.5714],18);L.control.zoom({position:'bottomright'}).addTo(liveMap);L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:20,attribution:'Tiles © Esri — Source: Esri, Maxar, Earthstar Geographics, and GIS User Community'}).addTo(liveMap);const marker=L.marker(state.coords||[23.0225,72.5714]).addTo(liveMap).bindPopup('Location context only. The demo roof is not georeferenced to this building.');liveMap.on('click',e=>{marker.setLatLng(e.latlng);state.coords=[e.latlng.lat,e.latlng.lng];state.location=state.coords.map(n=>n.toFixed(5)).join(', ');document.querySelector('.map-top strong').textContent=state.location;save();marker.bindPopup('Selected location saved. Use manual roof dimensions in the roof editor.').openPopup();});setTimeout(()=>liveMap.invalidateSize(),100);}
function searchLocation(){modal('Find your location',`<div class="dialog-body"><p class="muted">Search an address, enter coordinates, or use your location. Searches use Photon and OpenStreetMap Nominatim. Try a locality, landmark, PIN code plus city, or paste coordinates from your map. Imagery is displayed only; it is not sent to AI.</p><form id="search-form"><label class="field">Address or city<input id="search-query" placeholder="Locality, landmark, PIN code + city, or lat, lon" required minlength="2"></label><button class="primary">${icon('search')} Search map</button><button class="outline" type="button" id="geolocate">${icon('locate')} My location</button></form><div id="search-results"></div><hr><form id="coords-form"><div class="form-grid"><label class="field">Latitude<input name="lat" type="number" min="-85" max="85" step="any" value="${state.coords?.[0] ?? 23.0225}" required></label><label class="field">Longitude<input name="lng" type="number" min="-180" max="180" step="any" value="${state.coords?.[1] ?? 72.5714}" required></label></div><button class="outline">Use coordinates</button></form></div>`);const use=(coords,label)=>{state.coords=coords;state.location=label;state.view='satellite';save();$('#dialog').close();render();};$('#coords-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),lat=Number(f.get('lat')),lng=Number(f.get('lng'));use([lat,lng],`${lat.toFixed(4)}, ${lng.toFixed(4)}`);};$('#geolocate').onclick=()=>{if(!navigator.geolocation)return toast('Geolocation is unavailable. Enter coordinates instead.');navigator.geolocation.getCurrentPosition(p=>use([p.coords.latitude,p.coords.longitude],'My selected location'),()=>toast('Location was unavailable or permission was declined.'),{timeout:10000});};$('#search-form').onsubmit=async e=>{
  e.preventDefault();
  const form = e.currentTarget;
  const query = form.querySelector('input').value.trim();
  const results = $('#search-results');
  const coordinates = parseCoordinates(query);
  if (coordinates) return use(coordinates, coordinates.map(n=>n.toFixed(5)).join(', '));
  if (query.length < 2) return;
  const submit = form.querySelector('button');
  submit.disabled = true;
  results.textContent = 'Searching for matching places…';
  try {
    const {found, unavailable} = await lookupLocation(query);
    if (!results.isConnected || !$('#dialog').open) return;
    results.replaceChildren();
    for (const place of found) {
      const button = document.createElement('button');
      button.className = 'search-result';
      button.textContent = place.label + ' · ' + place.source;
      button.onclick = () => use(place.coords, place.label);
      results.append(button);
    }
    if (!found.length) results.textContent = unavailable
      ? 'Search providers are unavailable. You can still enter coordinates, use your location, or click the satellite map to place a pin.'
      : 'No matching places. Try the locality or a nearby landmark followed by the city, or enter coordinates and adjust the pin on the satellite map.';
  } finally {
    submit.disabled = false;
  }
};}
if(state.surveys)rows.splice(0,rows.length,...state.surveys);
$('#dialog').addEventListener('close',()=>{$('#dialog').classList.remove('wide');render();});
render();
